// Generated from the individually edited RU event-outcomes catalog (E221-E290).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E221_E290 = Object.freeze({"E221.1":{"s":"Мародёры выбивают древнюю дверь, а Сев наконец добирается до своего черепа. В усыпальнице находят золото, которым грабители неохотно делятся.","f":"При первом ударе по двери из стен выходят хранители усыпальницы. Начинается стычка."},"E221.2":{"s":"Вы платите мародёрам за уход, и те убирают инструменты. Сев остаётся у решётки слушать советы собственной головы."},"E221.3":{"s":"{{heroName}} освобождает решётку, не задев погребальных печатей. Сев возвращает череп на место и благодарит золотом.","f":"Каменная плита срывается при работе, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Решётка обрушивается, но никто из допустимых бойцов не получает тяжёлого ранения. Череп остаётся за камнем."}},"E221.4":{"s":"Вы оставляете Сева возле усыпальницы. «Попробуй вспомнить, что было в голове!» — кричит череп вслед."},"E222.1":{"s":"Вы входите в часовню и прерываете беззвучный строй. Среди подношений освобождённого хора обнаруживается золото.","f":"Чужая песня срывается на пронзительный беззвучный удар, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Хор обрушивает на гостей невидимый звук, но никто из допустимых бойцов не получает тяжёлого ранения. Пение не прекращается."}},"E222.2":{"s":"Вы оставляете Эмме провизию на дорогу и советуете покинуть дом до ночи. За спиной призраки снова открывают рты в одинаковом ритме."},"E222.3":{"s":"{{heroName}} ведёт безмолвный обряд, не давая хору нового голоса. Эмма благодарит золотом и припасами за наступившую тишину.","f":"Обряд отражается от стен обратной волной, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Безмолвный обряд срывается, но никто из допустимых бойцов не получает тяжёлого ранения. Каждый по-прежнему слышит свою песню."}},"E222.4":{"s":"Вы закрываете уши и проходите мимо часовни. За дверью Эмма остаётся одна с шестью невидимыми мелодиями."},"E223.1":{"s":"Пек аккуратно собирает пальцы в походный мешочек и принимает предложение Короля. У отряда появляется дисциплинированный, хотя и хрупкий новобранец.","f":"При последней проверке у Пека отваливается нога, и он просит перенести вступление в отряд. Нанять его не удаётся.","v":{"rs":"Пек готов служить, но свободного места нет. Йора передаёт золотую компенсацию, а скелет ищет другое назначение."}},"E223.2":{"s":"Вы отдаёте Йоре золото за запасные ремни и снаряжение Пека. Капитан делится походными припасами и советом держать всё по карманам."},"E223.3":{"s":"{{heroName}} проверяет, как Пек держит строй, и находит ему место без резких разворотов. Скелет вступает в отряд.","f":"Даже при помощи {{heroName}} Пек снова теряет кисть на повороте. Испытание приходится завершить без найма.","v":{"rs":"{{heroName}} подтверждает пригодность Пека к службе, но взять бойца нельзя. Йора передаёт отряду золото вместо пополнения."}},"E223.4":{"s":"Вы желаете Пеку найти подходящий строй. Скелет отдаёт честь, поправляет пальцы и возвращается к капитану."},"E224.1":{"s":"Вы оплачиваете комнаты и ночуете, стараясь не считать гостей. Утром Вела выдаёт припасы, хотя дощечка у входа теперь показывает ещё меньше мест."},"E224.2":{"s":"За запертой дверью оказывается старый счётный шкаф с золотом, а невидимый голос наконец замолкает.","f":"Дверь распахивается в коридор, заполненный вооружёнными чужаками, которых дом явно насчитал заранее. Начинается стычка."},"E224.3":{"s":"{{heroName}} вскрывает замок снаружи и достаёт золотой тайник, не переступая порог. Дощечка у входа дрожит, но не меняет числа.","f":"За дверью срабатывает скрытый засов, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Запертая комната отвечает опасным ударом, но никто из допустимых бойцов не получает тяжёлого ранения. Замок остаётся цел."}},"E224.4":{"s":"Вы покидаете постоялый дом до следующего пересчёта. Вела кричит вслед, что свободных комнат снова стало четыре."},"E225.1":{"s":"Жрец Морт наконец признаёт, что покойный был человеком нелёгким. Хель радостно кивает и оставляет золото за честную церемонию.","f":"Морт отказывается произносить речь, от которой живым станет ещё обиднее. Хель спорит с ним прямо у гроба."},"E225.2":{"s":"Вы просите Морте завершить церемонию ради родных, и Хель уступает им последнее слово. Семья делится припасами за восстановленный покой."},"E225.3":{"s":"{{heroName}} составляет речь, в которой Хель остаётся несносным, но любимым родственником. Покойник довольным жестом отдаёт золото, а семья — провизию.","f":"{{heroName}} находит слишком мало общего между памятью родных и требованиями Хеля. Речь приходится отложить."},"E225.4":{"s":"Вы уезжаете, пока процессия выбирает подходящее прилагательное для Хеля. Покойник по-прежнему настаивает на слове «невыносимый»."},"E226.1":{"s":"Кшш забирает припасы, медленно расправляет восемь ног и позволяет надеть седло. Вирра благодарит золотом за спасённый день."},"E226.2":{"s":"Вы помогаете усадить седло на Кшша, и паук наконец встаёт со своей подстилки. Вирра платит золотом за помощь.","f":"Кшш отбивается лапами от седла, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Паук опрокидывает помощников, но никто из допустимых бойцов не получает тяжёлого ранения. Седло остаётся на земле."}},"E226.3":{"s":"{{heroName}} находит под ремнями седла натёртую пластину, которая причиняла Кшшу боль. Вирра даёт золото и припасы, когда паук спокойно поднимается.","f":"{{heroName}} проверяет все ремни, но не находит причины отказа Кшша. Паук продолжает сторожить корзину."},"E226.4":{"s":"Вы оставляете Вирру обсуждать трудовое право с восьминогим работником. Кшш придвигает к себе корзину ещё на одну лапу."},"E227.1":{"s":"Вы задерживаете заказчика в серебряной маске и находите при нём золото за исполненный договор. Сарисс забирает контракт как доказательство обмана.","f":"Человек в маске зовёт охрану, а Сарисс бросается к нему с кинжалом. Начинается стычка."},"E227.2":{"s":"Вы выплачиваете гильдии золото и выкупаете смертельный заказ вместе с печатями. Сарисс наконец может убрать свои кинжалы."},"E227.3":{"s":"{{heroName}} находит в правилах гильдии запрет на тождество заказчика, исполнителя и жертвы без специального согласия. Гильдия возвращает золото.","f":"{{heroName}} находит лишь пункт о штрафе за пересмотр уже принятого заказа. Отряд теряет золото, а дело остаётся открытым."},"E227.4":{"s":"Вы не вмешиваетесь в контракт, где убийца сама числится жертвой. Сарисс ещё долго смотрит на чай заказчика, не прикасаясь к своим клинкам."},"E228.1":{"s":"Вы не считаете углы и находите разведчиков у стены, которая всё время была рядом. Зайр платит золотом за возвращение людей.","f":"Комната меняет размеры прямо на ходу, и {{affectedHeroName}} получает тяжёлое ранение от сдвинувшейся стены.","v":{"nf":"Восьмиугольная комната перестраивается, но никто из допустимых бойцов не получает тяжёлого ранения. Разведчиков не находят."}},"E228.2":{"s":"Вы перекрываете вход и оставляете башню без новых посетителей. Из восьмого угла ещё раз доносится голос пропавшего разведчика."},"E228.3":{"s":"{{heroName}} ведёт поиск по звуку шагов вместо подсчёта углов. Разведчики выбираются наружу и благодарят золото и припасами.","f":"Чужая геометрия замыкается вокруг {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Комната закручивает путь обратно к двери, но никто из допустимых бойцов не получает тяжёлого ранения. Поиск прекращается."}},"E228.4":{"s":"Вы оставляете Зайра возле башни. Изнутри доносится радостное: «Кажется, нашли девятый!»"},"E229.1":{"s":"Вы платите Нирису за обходной путь и проходите мимо кристалла с его бесконечными вопросами. Из камня доносится обиженное «неинтересно»."},"E229.2":{"s":"Вы рассказываете историю, которой не слышал никто из стоящих рядом, и кристалл в восторге открывает проход с золотом.","f":"Кристалл объявляет рассказ скучным и вызывает своих вооружённых хранителей. Начинается стычка."},"E229.3":{"s":"После удара кристалл раскалывается, открывая золотые жилы внутри. Нирис смотрит на вас так, будто впервые потерял спор с минералом.","f":"Защитный кристалл отвечает ударом и призывает стражу прохода. Начинается битва."},"E229.4":{"s":"Вы разворачиваетесь, не предложив кристаллу никакой истории. Он кричит вслед вопрос, на который никто уже не обязан отвечать."},"E230.1":{"s":"Вы убеждаете Сейру и Велиса принять обычный договор, пока пауки дерутся за пустые рамы. Дома выплачивают золото за завершённое перемирие.","f":"Сейра объявляет бумажный договор нарушением обычаев, и спор переходит в стычку."},"E230.2":{"s":"Вы дарите обоим домам золото, выигрывая время для новых переговоров. Посланники передают припасы в ответ, а пауков разводят по разным шатрам."},"E230.3":{"s":"{{heroName}} ведёт переговоры вдали от дерущихся пауков, и оба дома соглашаются подписать перемирие на уже готовой паутине. Отряд получает золото и припасы.","f":"{{heroName}} пытается договориться о тексте, но дома требуют сперва определить виновного в разрыве последней паутины. Подписи нет."},"E230.4":{"s":"Вы не берётесь быть третьим домом между Сейрой, Велисом и их пауками. За спиной очередная рама с грохотом падает на землю."},"E231.1":{"s":"Вы оплачиваете Моро испорченный торт и заставляете обоих убийц убрать клинки. Кондитер сразу спрашивает, кто возместит разбитые тарелки."},"E231.2":{"s":"Лис и Шаэль соглашаются возместить ущерб кондитеру, а часть золота передают отряду за посредничество.","f":"Оба ассасина обвиняют вас в поддержке соперника и переводят кинжалы на новых гостей. Начинается стычка."},"E231.3":{"s":"{{heroName}} находит следы сапог и устанавливает, кто первым перешагнул торт и нарушил прикрытие. Убийцы выплачивают золото за точный разбор.","f":"{{heroName}} видит лишь перемешанные следы в креме и не может отделить шаги Лиса от Шаэль. Спор продолжается."},"E231.4":{"s":"Вы оставляете двух убийц возле разрушенного торта. Моро громко требует вернуть хотя бы серебряную подставку."},"E232.1":{"s":"Вы отвечаете, что вопрос весит столько, сколько готов выдержать отвечающий, и дверь неожиданно отходит. В шахте находят золото.","f":"На очередной ответ дверь становится тяжелее и проседает, требуя укрепить пол. На материалы уходят припасы."},"E232.2":{"s":"Вы обходите загадочную дверь через соседнюю кладку и выносите из шахты припасы.","f":"Соседняя стена осыпается под инструментами, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Кладка рассыпается, но никто из допустимых бойцов не получает тяжёлого ранения. Проход остаётся закрытым."}},"E232.3":{"s":"{{heroName}} укрепляет дверную раму и поднимает створку рычагами, не задав ни одного вопроса. За ней лежат золото и припасы.","f":"Камень сдвигается на руку {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Тяжёлая плита сорвается с опор, но никто из допустимых бойцов не получает тяжёлого ранения. Шахтный вход не открыть."}},"E232.4":{"s":"Вы оставляете Брокка и его шахтёров возле двери, которая тяжелеет от вопросов. На прощание мастер велит больше ничего не спрашивать."},"E233.1":{"s":"В одной из новых шапок обнаруживаются золотые кольца Грима, а в другой — аккуратно заплетённая прядь бороды. Купец выплачивает награду золотом.","f":"Подозреваемые принимают обыск за оскорбление всего рода и бросаются защищать свои шапки. Начинается стычка."},"E233.2":{"s":"Вы передаёте Гриму золото за пропавшие украшения. Купец благодарит, но обещает продолжить розыск сорока семи лет роста."},"E233.3":{"s":"{{heroName}} находит на полу свежие волоски и след дорогого лезвия, ведущий к тайнику с кольцами. Грим выдаёт золото за разгадку.","f":"{{heroName}} обнаруживает, что все четверо одинаково посещали комнату ночью. Уверенно назвать похитителя не получается."},"E233.4":{"s":"Вы оставляете Грима, Нола и четырёх подозреваемых в новых шапках. Купец требует немедленно запретить продажу ножниц в городе."},"E234.1":{"s":"Вы входите в штольню и находите старую кассу у рабочего забоя. Золото достаётся отряду, но хозяев кирок так и не видно.","f":"За поворотом тоннеля появляется вооружённая бригада, не желающая показывать лица. Начинается битва."},"E234.2":{"s":"Вы забираете часть руды из уже загруженной вагонетки и продаёте её за золото.","f":"Из шахты выходят вооружённые охранники и требуют вернуть чужую выработку. Начинается стычка."},"E234.3":{"s":"{{heroName}} проверяет трещины после обвала и находит безопасное место для извлечения ценной руды. Кора платит золотом за обследование.","f":"С потолка срывается поддерживающая плита, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Опора обваливается, но никто из допустимых бойцов не получает тяжёлого ранения. Вход приходится закрыть."}},"E234.4":{"s":"Вы не трогаете вагонетку неизвестных работников. На борту следующей появляется новая сегодняшняя дата."},"E235.1":{"s":"К утру кружка пустеет, хотя никто не подходил к креслу. Дагна благодарит отряд припасами за терпение.","f":"На рассвете кружка остаётся полной, а ученики тревожно смотрят на Дагну. Обычай не даёт ответа."},"E235.2":{"s":"Вы незаметно опустошаете кружку, и Дагна выдаёт золото за восстановленный знак. Учеников хватает на то, чтобы никто не задавал вопросов.","f":"Дагна замечает подмену, и за попытку обмана приходится отдать припасы. Кружку снова ставят перед креслом."},"E235.3":{"s":"{{heroName}} проводит обряд памяти, и ученики впервые рассказывают о мастере без страха перед пустой кружкой. Дагна дарит золото и припасы.","f":"{{heroName}} не находит способа узнать, кто выпивал эль прежде. Дагна оставляет кружку стоять до следующего утра."},"E235.4":{"s":"Вы оставляете Дагну ждать ответа от пустого кресла. Ученики спорят, можно ли хотя бы переставить кружку ближе к краю."},"E236.1":{"s":"Вы наблюдаете за третьим выстрелом из безопасного укрытия, и ядро наконец летит вперёд. Бели платит золото за свидетелей удачного испытания.","f":"Ядро снова вылетает назад и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Третий выстрел уходит назад, но никто из допустимых бойцов не получает тяжёлого ранения. Испытание признают неудачным."}},"E236.2":{"s":"Вы покупаете у расчёта припасы и отходите от стрельбища до новых опытов. Торр уверяет, что опасной теперь считается только задняя полусфера."},"E236.3":{"s":"{{heroName}} замечает перевёрнутый зарядный канал и устраняет ошибку. Пушка стреляет вперёд, а дварфы награждают золотом.","f":"Во время исправления запала срабатывает обратная отдача, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Запальный механизм даёт опасный толчок, но никто из допустимых бойцов не получает тяжёлого ранения. Исправление откладывают."}},"E236.4":{"s":"Вы уходите до третьего выстрела. За спиной Бели спорит с Торром, какая сторона теперь официально считается передней."},"E237.1":{"s":"Вы признаёте поломку первой бригады страховым случаем, и Хельда выплачивает деньги. За разбирательство отряду выдаётся золото.","f":"Вторая бригада обвиняет решение в мошенничестве и хватает инструменты как оружие. Начинается стычка."},"E237.2":{"s":"Вы отдаёте средства второй бригаде, и она благодарит отряд припасами. Первая требует немедленно пересчитать размер несчастья.","f":"Первая бригада объявляет распределение фонда несправедливым и вызывает соперников на стычку."},"E237.3":{"s":"{{heroName}} сравнивает записи и доказывает, где авария настоящая, а где дорогая имитация. Хельда платит золотом и припасами за сохранённый фонд.","f":"{{heroName}} обнаруживает, что обе бригады пользуются одинаковыми сомнительными актами. Решение приходится отложить."},"E237.4":{"s":"Вы не берётесь распределять общий фонд взаимной ненависти. Хельда садится прямо на сундук и просит всех пока ничего не ломать."},"E238.1":{"s":"Вы платите Азелу за ключ с понятными условиями, а он выдаёт его вместе с припасами для дороги. Демон предупреждает ещё об одном мелком недостатке."},"E238.2":{"s":"Вы берёте ключ вопреки предупреждению, и он открывает маленький золотой тайник у дорожного камня. Азел искренне удивляется.","f":"Ключ обжигает ладонь Короля, причиняя тяжёлое ранение. Азел устало произносит: «Я же просил не брать».","v":{"nf":"Ключ срабатывает опасно, но Король не получает тяжёлого ранения. Замка, ради которого он был нужен, вы не находите."}},"E238.3":{"s":"Вы требуете возместить время на опасные предложения, и Азел, мечтая закончить торг, отдаёт золото.","f":"Демон объявляет требование вымогательством и вызывает вооружённых помощников. Начинается стычка."},"E238.4":{"s":"Вы благодарите Азела за редкую торговую честность и уходите без ключа. Он облегчённо закрывает коробку с опасным товаром."},"E239.1":{"s":"Вы делитесь припасами с бесами, и толпа наконец перестаёт грызть тарелки. Малг передаёт золото за спасённую посуду."},"E239.2":{"s":"Вы помогаете повару оттеснить бесов от кухни, и Малг платит золотом за возможность вновь включить печь.","f":"Голодные бесы принимают вас за новых раздатчиков и набрасываются с ножами и вилками. Начинается стычка."},"E239.3":{"s":"{{heroName}} выстраивает бесов в очередь и отделяет тарелки от того, что можно есть. Малг награждает золотом и припасами.","f":"{{heroName}} не успевает объяснить разницу между едой и посудой, и очередь разваливается. Кухня остаётся закрытой."},"E239.4":{"s":"Вы уходите, а козёл трусцой следует за отрядом до поворота. Малг кричит вслед, что это вообще-то его обед."},"E240.1":{"s":"Пять минут проходят, мир остаётся цел, и демоны выплачивают выигрыш золотом. Зерр требует занести в журнал «почти сбылось».","f":"Красные небеса пугают игроков, ставки пересчитывают по новым правилам, и выигрыша вам не выплачивают."},"E240.2":{"s":"Вы заставляете Зерра прекратить истерику на площади, и благодарные прохожие платят золотом за наступившую тишину.","f":"Демоны считают попытку остановить пророка посягательством на их развлечения. Начинается стычка."},"E240.3":{"s":"{{heroName}} находит над дорогой редкое атмосферное явление, а не начало апокалипсиса. Демоны благодарят припасами за сэкономленный страх.","f":"{{heroName}} не успевает установить причину красного неба до конца пяти минут. Зерр объявляет это дополнительным доказательством."},"E240.4":{"s":"Вы отходите от Зерра и пересчитываете оставшиеся минуты. Мир не заканчивается, но пророк уже готовит объяснение."},"E241.1":{"s":"Вы находите потерянный договор в придорожной канаве, где Тев уже трижды искал. Демон платит золотом за спасённое место в преисподней.","f":"Бумага не находится ни в сумках, ни под копытами, а архивариус уже близко. Тев просит хотя бы не рассказывать о нём начальству."},"E241.2":{"s":"Вы передаёте Теву золото за прекращение поисков и отсылаете его прочь. Крестьянин довольно объявляет это лучшей сделкой за сорок лет."},"E241.3":{"s":"{{heroName}} требует предъявить подлинник, и Тев не может доказать обязательство без бумаги. Демон откупается золотом за прекращение разбирательства.","f":"Тев вызывает адских приставов, сочтя юридический спор препятствием взысканию. Начинается стычка."},"E241.4":{"s":"Вы оставляете Тева рыться в канаве, а крестьянина — наслаждаться свободой от доказательств. До заката остаётся всё меньше времени."},"E242.1":{"s":"Вы отдаёте дрожащему демону припасы, и он наконец перестаёт стучать зубами. Рох благодарит золотом за помощь необычному гостю."},"E242.2":{"s":"Вы переносите демона к раскалённому горну, где ему становится терпимо. Рох делится припасами за спасённое одеяло и печь.","f":"Во время переноски демон непроизвольно вспыхивает, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Опасная вспышка срывает переноску, но никто из допустимых бойцов не получает тяжёлого ранения. Демон остаётся у костра."}},"E242.3":{"s":"{{heroName}} устраивает носилки с жаропрочным покрытием, и демона доставляют к кузне без пожара. Рох платит золотом и добавляет припасы.","f":"{{heroName}} выясняет, что ни одна доступная ткань не выдержит жара. Переноску приходится отложить."},"E242.4":{"s":"Вы оставляете Роха с демоном под дымящимся одеялом. Кузнец уже ищет второе, потолще."},"E243.1":{"s":"Вы находите корову в лавовой кладовой и выводите её через сарай. Фермеры благодарят припасами, а Ксал извиняется за ошибку адреса.","f":"Бесы объявляют корову частью адского инвентаря и берутся за оружие. Начинается стычка."},"E243.2":{"s":"Вы запираете неверно настроенный портал и возвращаете сарай хозяевам. Ксал перед закрытием бросает золотую плату за исправленную ошибку.","f":"Адская дверь сопротивляется закрытию, и через проём вырываются вооружённые стражи. Начинается стычка."},"E243.3":{"s":"{{heroName}} вынимает раму вместе с креплениями, и портал исчезает, не повредив сарай. Фермеры расплачиваются золотом и припасами.","f":"Рама резко меняет вес, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Портальная рама падает, но никто из допустимых бойцов не получает тяжёлого ранения. Дверь остаётся открытой."}},"E243.4":{"s":"Вы обходите сарай по широкой дуге. Позади фермеры снова требуют корову, а Ксал — карту третьей лавовой галереи."},"E244.1":{"s":"Вы предлагаете Риэлю потратить приготовленное благословение на помощь всей деревне. Ангел раздаёт припасы, а выздоровевшая старуха первой благодарит травницу.","f":"Риэль не может изменить назначение уже подготовленного чуда. Деревня остаётся без дополнительной помощи."},"E244.2":{"s":"Вы оставляете деревне золото от имени Короля. Риэль стоит рядом, пытаясь решить, считается ли это чудом без сияния."},"E244.3":{"s":"{{heroName}} помогает Риэлю превратить запоздалый обряд в тихое благословение деревни. Благодарные жители делятся золотом и припасами.","f":"{{heroName}} не находит способа провести обряд без того, кому он был предназначен. Ангелу остаётся принять опоздание."},"E244.4":{"s":"Вы оставляете Риэля и травницу спорить о том, кто из них лучше помог больной. Старуха приглашает обоих на чай."},"E245.1":{"s":"Вы отдаёте Лиону принесённое ветром перо, и Саф после долгой проверки признаёт его годным. Благодарный ангел делится припасами.","f":"Инспектор находит у пера другую отметку и отказывается принимать его в счёт утраты. Ведомость остаётся открытой."},"E245.2":{"s":"Вы оплачиваете недостающее перо из казны, и Саф ставит долгожданную печать. Лион смотрит на пустое место в крыле с облегчением."},"E245.3":{"s":"{{heroName}} находит в боевом рапорте запись о потере пера при исполнении долга. Саф закрывает дело и выплачивает золото за разбирательство.","f":"{{heroName}} не обнаруживает надлежащей подписи на рапорте. Инспектор требует оформлять всё заново."},"E245.4":{"s":"Вы проходите мимо небесной проверки, оставляя Лиона и Сафа над увеличительным стеклом. Ветер приносит ещё одно белое перо."},"E246.1":{"s":"Вы признаёте облако небесной собственностью, и Орис платит золото за решение. Облако тут же обливает его дождём.","f":"Облако уходит с линии границы, не дожидаясь оформления небесной юрисдикции. Спор не разрешён."},"E246.2":{"s":"Пограничник получает право досмотреть облако и благодарит отряд припасами. Неизвестно, где он собирается искать контрабанду.","f":"Орис не признаёт право земного чиновника досматривать небо. Досмотр отменяется до решения спора."},"E246.3":{"s":"Вы ждёте, пока облако само уплывёт из зоны спора. Два чиновника одновременно объявляют это законным пересечением границы."},"E246.4":{"s":"Вы разгоняете обе стороны и забираете золото, назначенное за срочное рассмотрение дела. Облако исчезает прежде, чем спор возобновится.","f":"Орис и пограничник зовут охрану с обеих сторон дороги. Начинается стычка."},"E247.1":{"s":"Вы будите Мерада сильным ударом в плечо, и ангел впервые за девяносто лет опускает копьё. Паломники благодарят золотом.","f":"Трещина под ногами стража отвечает горячим выбросом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Раскалённая трещина расширяется, но никто из допустимых бойцов не получает тяжёлого ранения. Ангел остаётся неподвижным."}},"E247.2":{"s":"Вы отводите паломников с холма до того, как земля окончательно растрескивается. Священник снабжает отряд припасами.","f":"Паломники отказываются уходить от стража, которого благодарили всю жизнь. Эвакуация не удаётся."},"E247.3":{"s":"{{heroName}} обнаруживает под холмом древнюю печать, которую Мерад удерживал своим бдением. За находку священник выдаёт золото и припасы.","f":"Попытка приблизиться к печати вызывает всплеск жара, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Печать отталкивает исследователей, но никто из допустимых бойцов не получает тяжёлого ранения. Истинная угроза остаётся нераскрытой."}},"E247.4":{"s":"Вы оставляете Мерада на страже, не нарушая его девяностолетний пост. Трещины под копьём медленно ползут к дороге."},"E248.1":{"s":"Вы покупаете у Фосса припасы и получаете их между двумя ящиками с креплениями для крыльев. Очередь ангелов движется на одно место вперёд."},"E248.2":{"s":"Вы разгружаете столы Фосса и рассортировываете забытые заказы. Мастер выдаёт золотую плату за освобождённую мастерскую.","f":"При разборке складских ящиков портится часть собственных припасов. Очередь всё ещё не двигается."},"E248.3":{"s":"{{heroName}} закрепляет тяжёлые накладки и помогает Кери расправить крыло. Фосс платит золотом и добавляет припасы.","f":"{{heroName}} видит, что часть креплений сделана под другой размер крыла. Срочную работу приходится отложить."},"E248.4":{"s":"Вы покидаете мастерскую, не вступая в очередь на ремонт чужих крыльев. Фосс уже спорит с ангелом, который принёс одно перо."},"E249.1":{"s":"Вы выбиваете дверь часовни и находите золотые подношения возле пустого стула. Свет гаснет, едва отряд проходит порог.","f":"Из сияния выходят вооружённые хранители, которым не понравился взлом. Начинается битва."},"E249.2":{"s":"Вы отводите людей от запертой часовни, не позволяя любопытным подойти к стенам. Стул внутри продолжает скрести по полу."},"E249.3":{"s":"{{heroName}} входит в часовню и выясняет, что свет исходит из старой печати под стулом. Сестра Авел благодарит золотом и припасами за возвращённое спокойствие.","f":"Печать вспыхивает при приближении, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Световой удар останавливает осмотр, но никто из допустимых бойцов не получает тяжёлого ранения. Часовня остаётся закрытой."}},"E249.4":{"s":"Вы уходите до рассвета, не проверяя источник света. Сквозь стены часовни по-прежнему видны тени деревьев."},"E250.1":{"s":"Вы убеждаете Иару и Веха разделить награду, и оба впервые признают заслугу другого. Семья ребёнка выдаёт отряду золото за прекращённый спор.","f":"Ни ангел, ни демон не соглашается делить честь спасения. Девочка тихо говорит, что предпочла бы разделить самих спорщиков."},"E250.2":{"s":"Вы отдаёте семье золото, не выясняя, кому достанется слава. Родители благодарят отряд припасами."},"E250.3":{"s":"{{heroName}} просит девочку назвать то, что помогло ей первой: свет дал убежать, страх остановил преследователей. Оба спасителя принимают решение и передают золото с припасами.","f":"{{heroName}} предлагает общий вердикт, но Иара и Вех всё равно спорят о порядке чудес. Награда не распределена."},"E250.4":{"s":"Вы уходите, пока спор ангела и демона не превратился в трактат о природе добра. Девочка стирает мелом свой круг."},"E251.1":{"s":"В красной пещере вы находите забытый драконий тайник с золотом. Рахс долго рассматривает собственную приписку и признаёт, что предупреждение было весьма полезным.","f":"Красная пещера оказывается логовом вооружённых существ, разбуженных поисками. Начинается битва."},"E251.2":{"s":"В одной из обычных пещер вы обнаруживаете небольшую часть забытого клада. Рахс благодарит золотом за находку.","f":"Поиски затягиваются до ночи и расходуют припасы, но очередная отметка на карте ведёт в пустоту."},"E251.3":{"s":"{{heroName}} проверяет несколько крестов, отделяя старые отметки от свежих. Отряд находит золото в пещере без названия.","f":"На обратном пути из ущелья {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Проверка пещер заканчивается опасным обвалом, но никто из допустимых бойцов не получает тяжёлого ранения. Клада не находят."}},"E251.4":{"s":"Вы желаете Рахсу терпения и оставляете его с внуками и картой. Старый дракон уже задумчиво ставит новый крест."},"E252.1":{"s":"Вы поддерживаете желание Каары хранить отцовскую чешую в храме. Семья благодарит отряд припасами за решение.","f":"Каара не принимает решение без согласия брата и продолжает держать чешую перед семейным алтарём. Спор не заканчивается."},"E252.2":{"s":"Вы признаёте право Теша носить чешую на щите в память об отце. Он передаёт золото за поддержку.","f":"Каара отказывается отдавать чешую для щита и требует сначала обсудить волю матери. Уступки не происходит."},"E252.3":{"s":"{{heroName}} читает надпись на внутренней стороне чешуи и выясняет, какой обычай отец хотел сохранить. Семья прекращает спор и благодарит золотом и припасами.","f":"{{heroName}} не может разобрать последнее стёртое слово; ни Каара, ни Теш не готовы уступить. Чешуя остаётся между ними."},"E252.4":{"s":"Вы оставляете Каару и Теша перед материнским вопросом о памяти. Чешуя лежит на столе между храмом и щитом."},"E253.1":{"s":"Вы покупаете флакон драконьего дыхания и получаете от алхимика дорожные припасы как часть сделки. Молодой работник вновь склоняется к медной воронке."},"E253.2":{"s":"Вы добиваетесь, чтобы Сарр заплатил дракониду справедливую долю. За улаженную сделку отряду достаётся золото.","f":"Алхимик заявляет, что условия его труда никого не касаются, и зовёт вооружённых помощников. Начинается стычка."},"E253.3":{"s":"{{heroName}} обнаруживает в договоре удержания, которых юный драконид не понимал, и добивается пересчёта. Сарр отдаёт золото и припасы.","f":"{{heroName}} находит подписи на всех страницах, но не может доказать принуждение. Работник остаётся у воронки."},"E253.4":{"s":"Вы отказываетесь покупать огонь, которым зарабатывают на чужом изнеможении. Сарр торопливо заверяет следующего покупателя, что всё добровольно."},"E254.1":{"s":"Вы удерживаете пламя под проливным дождём до завершения ковки. Варек выплачивает обещанное золото, а Мира впервые улыбается.","f":"Дождь гасит горн, и на повторный розжиг уходят припасы. Варек объявляет это суровым, но полезным испытанием."},"E254.2":{"s":"Вы отдаёте припасы на топливо и материалы, и Мира успевает закончить работу до следующего ливня. Варек благодарит золотом."},"E254.3":{"s":"{{heroName}} устанавливает съёмный навес над горном, не разрушая кузнецовой традиции. Варек расплачивается золотом за сохранённый огонь.","f":"Опора навеса падает при порыве ветра, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Временное укрытие срывается ветром, но никто из допустимых бойцов не получает тяжёлого ранения. Горн снова гаснет."}},"E254.4":{"s":"Вы оставляете Варека спорить с дождём, а Миру — носить уголь. Кузнец уверяет, что металл когда-нибудь оценит упорство."},"E255.1":{"s":"Вы поддерживаете Кеша на каждом шаге, пока огромный доспех не достигает церемониального круга. Семья благодарит припасами.","f":"Кеш не может удержать шлем и садится прямо на площадке, не закончив путь. Церемонию приходится перенести."},"E255.2":{"s":"Семья соглашается, что взросление не измеряется размером прадедовского нагрудника. Наставник благодарит золотом за сохранённое достоинство Кеша.","f":"Наставник отвергает предложение изменить вековой обычай. Кеш продолжает звенеть в слишком большом доспехе."},"E255.3":{"s":"{{heroName}} учит Кеша двигаться короткими шагами и держать вес брони на бёдрах. Кеш проходит церемонию, семья платит золотом и припасами.","f":"При тренировке тяжёлая броня падает на {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Доспех опрокидывается на площадке, но никто из допустимых бойцов не получает тяжёлого ранения. Испытание прекращают."}},"E255.4":{"s":"Вы не вмешиваетесь в семейную традицию. За спиной Кеш делает первый шаг и исчезает внутри собственного шлема."},"E256.1":{"s":"Вы добираетесь до кипящего круга на озере и находите золотые предметы, поднявшиеся со дна. Рыбаки не решаются приблизиться к лодке.","f":"Из красного свечения поднимается вооружённое существо, вынуждая отряд вступить в битву."},"E256.2":{"s":"Вы покупаете у рыбаков припасы и уходите от странного озера. Сети у причала всё ещё горячие."},"E256.3":{"s":"{{heroName}} читает знаки на береговых плитах и узнаёт место древнего огненного источника. За открытие рыбаки передают золото и припасы.","f":"Тёплая чешуя вспыхивает в руках, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Чешуя даёт огненный выброс, но никто из допустимых бойцов не получает тяжёлого ранения. Происхождение свечения остаётся тайной."}},"E256.4":{"s":"Вы оставляете озеро не потревоженным. Красное свечение снова проходит по дну, пока рыбаки сворачивают сети."},"E257.1":{"s":"Вы выкупаете контракт у коллекционера, и Оври получает право сохранить собственный хвост. Он благодарит припасами и обещает читать мелкий шрифт."},"E257.2":{"s":"Вы отгоняете коллекционера с ножницами, а благодарный Оври передаёт золото за спасённый хвост.","f":"Коллекционер приводит вооружённую охрану для исполнения договора. Начинается стычка."},"E257.3":{"s":"{{heroName}} доказывает, что хвост нельзя поставить «после естественной смерти» немедленно, не изменив сам предмет сделки. Коллекционер возвращает золото.","f":"{{heroName}} находит условие о штрафе за расторжение. Отряду приходится отдать часть золота, а спор продолжается."},"E257.4":{"s":"Вы оставляете Оври между портным и коллекционером. Ножницы щёлкают, а лис впервые требует копию договора крупным шрифтом."},"E258.1":{"s":"Вы проводите час, спасая плащ Короля от трёх настойчивых львят. Раша благодарит припасами за целый выводок.","f":"Львята играют с обозом так увлечённо, что часть провизии оказывается разодрана. Раша возвращается к пустому мешку."},"E258.2":{"s":"Вы платите торговцу за дополнительный час присмотра, и он неохотно спускается с дерева. Один сапог остаётся у львят."},"E258.3":{"s":"{{heroName}} устраивает львятам охотничью игру без настоящей добычи. Раша благодарит золотом и припасами.","f":"Один из львят принимает руку за добычу, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Львята разгоняют сторожей по кустам, но никто из допустимых бойцов не получает тяжёлого ранения. Присмотр приходится прекратить."}},"E258.4":{"s":"Вы отказываетесь от должности няни и уходите, пока львята не обнаружили запасной плащ. Раша смотрит вслед с явным сожалением."},"E259.1":{"s":"Вы вручаете Бургу плату, и тот отступает на шаг ровно настолько, чтобы пропустить отряд. Знак на посту остаётся нетронутым."},"E259.2":{"s":"Вы объясняете Бургу, что двадцать три года без смены превращают приказ в ошибку. Он принимает довод, а караван делится припасами.","f":"Бург воспринимает спор с приказом как попытку прорваться силой и встаёт поперёк перевала. Начинается стычка."},"E259.3":{"s":"{{heroName}} переносит каменный знак вместе с разметкой поста, и Бург охраняет уже обочину. Караван благодарит золотом и припасами.","f":"При переноске знака {{affectedHeroName}} получает тяжёлое ранение под падающей плитой.","v":{"nf":"Знак срывается с креплений, но никто из допустимых бойцов не получает тяжёлого ранения. Пост остаётся перекрытым."}},"E259.4":{"s":"Вы тратите припасы на поиск другого перевала. Бург стоит на своём месте, не оборачиваясь к уходящему каравану."},"E260.1":{"s":"Вы садитесь рядом с Кха и обращаетесь к пустому месту, а невидимый собеседник оставляет золотой дар в золе. Гиена смеётся впервые вместе с кем-то.","f":"Чужой смех раздаётся прямо за спинами бойцов, и из костра выходят вооружённые тени. Начинается стычка."},"E260.2":{"s":"Вы отводите Кха от костра, и невидимый спутник не следует за ней. Стая благодарит припасами за возвращённый покой.","f":"Кха отказывается покидать друга, которого видит только она. Стая остаётся в страхе перед пустым местом."},"E260.3":{"s":"{{heroName}} находит в золе второй отпечаток лапы и понимает, что гость существует отдельно от Кха. Стая платит золотом за разгадку.","f":"Невидимое существо отвечает на проверку ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Невидимый гость выталкивает исследователей из круга света, но никто из допустимых бойцов не получает тяжёлого ранения. Кха продолжает смеяться."}},"E260.4":{"s":"Вы не садитесь к костру, где слышен смех только одного собеседника. Позади в золе появляется ещё один след лапы."},"E261.1":{"s":"Вы поддерживаете обвинение, и Мисса признаёт торговца-мышь виновным после проверки права на сыр. Истец благодарит золотом за решение.","f":"Судья не может доказать, что кусок сыра вообще кому-то принадлежал. Обвинение остаётся без решения."},"E261.2":{"s":"Вы защищаете мышь и указываете на отсутствие документов о владельце сыра. Благодарный торговец отдаёт припасы.","f":"Мисса находит накладную с именем истца и отказывается принять доводы защиты. Мыши остаётся ждать приговора."},"E261.3":{"s":"{{heroName}} изучает накладные, пока Мисса старается не смотреть на хвост ответчика. Стороны принимают вывод и передают золото с припасами.","f":"{{heroName}} выясняет, что сыр несколько раз перепродали без расписок. Право собственности установить не удаётся."},"E261.4":{"s":"Вы оставляете Миссу следить за порядком в кошачьем суде. Мышь старается держать хвост неподвижно."},"E262.1":{"s":"Вы идёте на ответный голос и находите старую закладку с золотом у каменного уступа. Мур узнаёт место, где когда-то стоял его дом.","f":"Из-за уступа выходят вооружённые незнакомцы, подражающие голосу сына Мура. Начинается стычка."},"E262.2":{"s":"Вы убеждаете Мура не отвечать незнакомому эху и прислушаться к словам внучки. Семья благодарит припасами.","f":"Мур повторяет фразу сына вновь, и издали звучит тот же странный ответ. Остановить его не удаётся."},"E262.3":{"s":"{{heroName}} обнаруживает, что второй голос приходит из старого акустического свода в скалах. Мур благодарит золотом и припасами за объяснение.","f":"В расщелине срывается каменная плита, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Опасная расщелина вынуждает прекратить поиски, но никто из допустимых бойцов не получает тяжёлого ранения. Второй голос не объяснён."}},"E262.4":{"s":"Вы оставляете Мура с внучкой у тихой равнины. Внука она зовёт уже своим голосом, не пытаясь повторить чужой."},"E263.1":{"s":"Вы признаёте правоту Г-17: условия службы не соответствуют договору. Ремонтник благодарит припасами за решение.","f":"Чиновник отвергает жалобу Г-17 и велит ему немедленно выйти под дождь. Голем не двигается с места."},"E263.2":{"s":"Вы поддерживаете чиновника, и голем получает предписание вернуться на патруль. За подтверждение приказа отряду выдаётся золото.","f":"Ремонтник показывает проржавевшие шарниры и добивается отсрочки приказа. Возобновить патруль не удаётся."},"E263.3":{"s":"{{heroName}} очищает сочленения и устанавливает защитные накладки от дождя. Чиновник выплачивает золото, а ремонтник добавляет припасы.","f":"Мокрый механизм зажимает инструмент, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Механизм даёт опасную отдачу, но никто из допустимых бойцов не получает тяжёлого ранения. Г-17 остаётся под навесом."}},"E263.4":{"s":"Вы не вмешиваетесь в спор о сухих условиях эксплуатации. Г-17 уходит глубже под крышу вслед за новой каплей дождя."},"E264.1":{"s":"Вы разбираете корпус А-9 и находите спрятанный голосовой модуль с ценными золотыми контактами. Хозяйка мастерской платит за возвращённую работу.","f":"Внутренний механизм срабатывает раньше, чем удаётся убрать руку, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Корпус отвечает внезапным ударом, но никто из допустимых бойцов не получает тяжёлого ранения. Источник голоса остаётся внутри."}},"E264.2":{"s":"Вы платите хозяйке мастерской за отключение автомата. А-9 шепчет «спасибо», а второй голос успевает сказать лишь первое слово."},"E264.3":{"s":"{{heroName}} различает два сигнала с разной задержкой и находит источник второго голоса без вскрытия. Хозяйка выдаёт золото за разгадку.","f":"Второй голос оборачивается опасной магической вспышкой, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Невидимый сигнал отталкивает исследователей, но никто из допустимых бойцов не получает тяжёлого ранения. А-9 продолжает шептать."}},"E264.4":{"s":"Вы обходите автоматон, не прислоняя ухо к его груди. Издалека слышно: «Не слушайте его»."},"E265.1":{"s":"Вы признаёте правоту К-4, и амбар переносят в другое место. Смотрительница платит золото за возобновлённую защиту.","f":"Жители отказываются сносить новый амбар и вызывают стражу против решения. Начинается стычка."},"E265.2":{"s":"Вы поддерживаете жителей и останавливаете башню, которая угрожает амбару. Деревня благодарит припасами.","f":"К-4 не принимает команду от людей, которые перекрыли ей свет. Выключить её пока не удаётся."},"E265.3":{"s":"{{heroName}} ставит отражающие панели так, чтобы утренний свет снова попадал на К-4. Деревня благодарит золотом и припасами.","f":"{{heroName}} обнаруживает, что доступные зеркала не выдержат ветра. Башня продолжает требовать передвинуть солнце."},"E265.4":{"s":"Вы оставляете К-4 спорить с амбаром и небесным светилом. Смотрительница уже ищет более терпеливого инженера."},"E266.1":{"s":"Вы оплачиваете долг за Лома и открываете ящик, не требуя служить новому хозяину. Деревянный автомат выбирается наружу сам."},"E266.2":{"s":"Вы признаёте право торговца распоряжаться долгом и получаете золото за решение. Лом из ящика громко заявляет, что не согласен.","f":"Девочка приводит сторонников Лома и требует прекратить продажу живого помощника. Начинается стычка."},"E266.3":{"s":"{{heroName}} обнаруживает в долговой книге, что Лом не указан среди заложенных вещей. Торговец возвращает золото за спор.","f":"{{heroName}} находит лишь неполные расписки, а торговец взыскивает плату за проверку. Отряд теряет золото."},"E266.4":{"s":"Вы не вмешиваетесь в продажу Лома. Из ящика раздаётся отчётливое: «Я всё слышу», и торговец поспешно отходит."},"E267.1":{"s":"Вы поднимаетесь к часам и обнаруживаете потайную нишу с золотом за смеющейся шестернёй. Второй голос в переулке умолкает.","f":"У механизмов вас встречают вооружённые ночные стражи, откуда-то знающие о вашем визите. Начинается стычка."},"E267.2":{"s":"Вы оплачиваете ночлег далеко от часов и получаете припасы от хозяина тихой гостиницы. Смех доходит сюда лишь слабым эхом."},"E267.3":{"s":"{{heroName}} задерживается у башни и находит второй, скрытый часовой механизм, отвечающий первым. Эм платит золотом за обнаруженную неисправность.","f":"В полночь башня отвечает на проверку ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Полуночный механизм срабатывает, но никто из допустимых бойцов не получает тяжёлого ранения. Смех продолжает звучать."}},"E267.4":{"s":"Вы покидаете площадь до темноты. Эм всё ещё ждёт момента, когда часы начнут смеяться."},"E268.1":{"s":"Автоматон признаёт настоящего Короля основным и открывает старое хранилище с золотом. Городской совет впервые единодушно выключает резервную корону.","f":"Машина объявляет обоих монархов действующими и поднимает вооружённую охрану крепости. Начинается битва."},"E268.2":{"s":"Вы распоряжаетесь разобрать резервного монарха, и среди деталей находят золото старого двора.","f":"Сторожевые механизмы расценивают приказ как покушение на престол. Начинается стычка."},"E268.3":{"s":"Вы оставляете запасного Короля выключенным. Архивист заносит в журнал, что основной экземпляр прибыл без повреждений."},"E268.4":{"s":"Вы платите архивисту и забираете припасы из подвала. Резервный монарх остаётся сидеть на своём железном троне."},"E269.1":{"s":"Вы выгоняете медведя из кровати Пела, и лесник благодарит золотом за возвращённую сторожку.","f":"Зверь просыпается от шума и бросается защищать чужую постель. Начинается стычка."},"E269.2":{"s":"Вы кладёте припасы у двери, а Пел продолжает ждать, пока квартирант сам освободит кровать. Из окна высовывается сонная морда."},"E269.3":{"s":"{{heroName}} выманивает медведя запахом еды и открывает Пелу путь в сторожку. Лесник благодарит золотом и припасами.","f":"Медведь резко выскакивает из двери, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Зверь отталкивает всех от крыльца, но никто из допустимых бойцов не получает тяжёлого ранения. Сторожка остаётся занятой."}},"E269.4":{"s":"Вы оставляете Пела на крыльце, а медведя — в его кровати под одеялом. Впервые лесник думает построить себе вторую сторожку."},"E270.1":{"s":"Вы идёте дальше и перехватываете золотую кассу разбойников, которые пришли по сигналу ворон. Добыча оказывается у отряда.","f":"Разбойники верно читают число карканий и выбирают удобное место для нападения. Начинается стычка."},"E270.2":{"s":"Вы оставляете птицам часть припасов, и вороны переключаются на еду вместо подсчётов. Отряд проходит мимо без новой тревоги."},"E270.3":{"s":"{{heroName}} следует за сигналами птиц и находит убежище разбойников с золотом. Вдова Нара благодарит за разоблачение.","f":"У засады разбойников {{affectedHeroName}} получает тяжёлое ранение прежде, чем успевает отступить.","v":{"nf":"Разведка обнаруживает засаду, но никто из допустимых бойцов не получает тяжёлого ранения. Золото разбойников остаётся недоступно."}},"E270.4":{"s":"Вы сворачиваете с дороги раньше следующего ряда ворон. Их карканье затихает среди деревьев."},"E271.1":{"s":"Белый олень приводит вас к лесному схрону с припасами, а серебряный звон раздаётся всё дальше. Зверь уходит без прикосновения.","f":"За откликнувшимися колокольчиками выходят вооружённые охотники, не желающие гостей. Начинается стычка."},"E271.2":{"s":"Вы снимаете серебряный колокольчик с оленьей шеи и продаёте его за золото. Зверь уходит молча.","f":"Олень ударяет рогами, защищаясь, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Олень резко отбивает руку и уходит, но никто из допустимых бойцов не получает тяжёлого ранения. Колокольчик остаётся у зверя."}},"E271.3":{"s":"{{heroName}} идёт за оленем на расстоянии и находит у лесных камней золото и припасы. Колокольчик не выдает скрытого разведчика.","f":"На лесном склоне {{affectedHeroName}} получает тяжёлое ранение, наткнувшись на скрытую ловушку.","v":{"nf":"Разведка натыкается на ловушку, но никто из допустимых бойцов не получает тяжёлого ранения. След оленя потерян."}},"E271.4":{"s":"Вы оставляете белого оленя с его колокольчиком и не идёте на зов. Три серебряных звона постепенно сливаются в один."},"E272.1":{"s":"Вы разбираете часть плотины и освобождаете затопленный тракт. Бобры немедленно принимаются за новую секцию.","f":"Бобры защищают сооружение и выводят на дорогу свой вооружённый сторожевой отряд. Начинается стычка."},"E272.2":{"s":"Вы оплачиваете Лему лодку и пересекаете затопленный участок. Один бобр внимательно следит за качеством переправы."},"E272.3":{"s":"{{heroName}} находит место для прохода без разрушения плотины, и Лем делится золотом и припасами за удачный проект.","f":"Бревно с плотины срывается, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Бревно срывает строительные работы, но никто из допустимых бойцов не получает тяжёлого ранения. Проход пока не открыт."}},"E272.4":{"s":"Вы тратите припасы на сухой обход затопленной дороги. За спиной бобры уносят очередной лист чертежа Лема."},"E273.1":{"s":"Вы вновь приводите пса к старому солдату и оставляете их вдвоём. Хозяин благодарит припасами за терпение.","f":"Пёс вырывается и возвращается на северный перекрёсток прежде, чем видит дом солдата. Примирить их не удаётся."},"E273.2":{"s":"Вы оставляете псу еду у перекрёстка и идёте дальше. Он ест, не отрывая взгляда от северной дороги."},"E273.3":{"s":"Вы платите трактирщику за заботу о старом псе. Тот обещает приносить еду каждый вечер, сколько потребуется."},"E273.4":{"s":"Вы не мешаете псу ждать того, кто ушёл когда-то на север. Старый солдат живёт совсем рядом, но перекрёсток остаётся пустым."},"E274.1":{"s":"Вы помогаете рыбакам удержать сети, пока улов не перестаёт тянуться к небу. Выбранную рыбу отдают отряду в припасы.","f":"Взлетающий карп срывает сеть с рук, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Сети вырываются в небо, но никто из допустимых бойцов не получает тяжёлого ранения. Улов потерян."}},"E274.2":{"s":"Вы добираетесь до берега и находите под местом взлёта рыб золотые предметы, выпавшие из сетей.","f":"Из тёмного облака над рекой спускается вооружённое существо. Начинается битва."},"E274.3":{"s":"{{heroName}} определяет, что тень притягивает речных существ через необычный воздушный поток. Рыбаки платят золотом и припасами за предупреждение.","f":"Сила из облака бьёт в берег, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Внезапный воздушный удар срывает наблюдения, но никто из допустимых бойцов не получает тяжёлого ранения. Источник тени скрывается."}},"E274.4":{"s":"Вы уходите под защиту скал, пока рыба продолжает подниматься в облако. Рыбаки ещё долго смотрят вверх с пустыми сетями."},"E275.1":{"s":"Вы платите Нилли золото за вчера, которое уже не вернуть. Фея принимает компенсацию и наконец отпускает торговца."},"E275.2":{"s":"Вы убеждаете Нилли, что прожитый день нельзя вернуть как товар, и торговец выплачивает отряду золото за защиту.","f":"Фея обвиняет вас в краже времени и зовёт своих вооружённых друзей. Начинается стычка."},"E275.3":{"s":"{{heroName}} заставляет Нилли объяснить, как вчера могло перейти в собственность другого. Фея отступает от требований и выдаёт золото.","f":"{{heroName}} запутывается в фейском договоре, а Нилли требует оплатить судебные минуты. Отряд теряет золото."},"E275.4":{"s":"Вы отказываетесь судить сделку за использованный день. Нилли спрашивает торговца, не продаст ли он ей завтрашнее утро."},"E276.1":{"s":"Вы оставляете муравьям припасы для свадебного пира, а они возвращают Керу сапог. Солдат благодарит золотом за спасённую обувь."},"E276.2":{"s":"Вы разгоняете муравьиный строй и возвращаете сапог владельцу. Кер платит золотом за избавление от босой службы.","f":"Фейские муравьи атакуют иголками строем, защищая свадебный дом. Начинается стычка."},"E276.3":{"s":"{{heroName}} предлагает муравьям пустую коробку взамен сапога, и те с радостью переносят свадьбу. Кер выдаёт золото и припасы.","f":"{{heroName}} не может понять церемониальные сигналы муравьёв, и те не соглашаются на обмен. Сапог остаётся с музыкой внутри."},"E276.4":{"s":"Вы желаете Керу лёгкой дороги и идёте дальше. Солдат прыгает на одной ноге вслед за собственной праздничной обувью."},"E277.1":{"s":"Вы отвечаете голосу, который гриб выбрал для вас, и находите в белом круге золотой тайник. Эл остаётся у поляны с чужими воспоминаниями.","f":"Гриб выпускает обжигающие споры, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Гриб выбрасывает опасные споры, но никто из допустимых бойцов не получает тяжёлого ранения. Разговор обрывается."}},"E277.2":{"s":"Вы поджигаете гриб снаружи круга, а среди его обугленных корней находите золото.","f":"Феи объявляют поджог нарушением запрета и выходят защищать поляну. Начинается стычка."},"E277.3":{"s":"{{heroName}} разбирает старые знаки на белых камнях и обнаруживает, как гриб заимствует чужие голоса. Феи благодарят золотом и припасами.","f":"Защитный круг вспыхивает и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Белые камни отвечают ударом света, но никто из допустимых бойцов не получает тяжёлого ранения. Тайна гриба остаётся без ответа."}},"E277.4":{"s":"Вы не вступаете в белый круг и оставляете Эл у гриба с материнским голосом. Феи молча следят за уходящими."},"E278.1":{"s":"Вы помогаете феям очистить капустную грядку от тли и получаете припасы от благодарной деревни. Божья коровка принимает парад победы.","f":"Насекомые прорывают строй, и часть походных припасов гибнет в суматохе. Кампания затягивается."},"E278.2":{"s":"Вы выдаёте деревне припасы на оборону грядки, а командир-божья коровка награждает отряд золотом."},"E278.3":{"s":"{{heroName}} организует смыв тли водой и спасает грядку без генерального сражения. Старейшины благодарят золотом и припасами.","f":"{{heroName}} не может подать воду к дальнему участку грядки. Феи остаются при прежнем плане атаки."},"E278.4":{"s":"Вы оставляете фей готовиться к великой капустной войне. Божья коровка стучит лапкой по щитам ещё усерднее."},"E279.1":{"s":"Вы везёте бабочку до следующей развилки, и она наконец расправляет крылья. Почтальон благодарит припасами за доставку.","f":"Бабочка устраивается на седле и отказывается лететь даже у нужной тропы. Адресат остаётся неизвестным."},"E279.2":{"s":"Вы вскрываете свиток и находите указание на золотой тайник возле дороги. Бабочка немедленно улетает.","f":"Печать с закрытым глазом вспыхивает, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Письмо отвечает опасным всплеском, но никто из допустимых бойцов не получает тяжёлого ранения. Прочесть его не удаётся."}},"E279.3":{"s":"{{heroName}} замечает, в какую сторону бабочка поворачивает усики перед каждой развилкой. Почтальон благодарит золотом и припасами за найденный маршрут.","f":"{{heroName}} не удаётся определить адрес по поведению насекомого, и бабочка продолжает сидеть на седле. Доставку откладывают."},"E279.4":{"s":"Вы возвращаете бабочку и свиток фее-почтальону. Она вздыхает и отправляется искать транспорт более послушный, чем Конь."},"E280.1":{"s":"Король надевает корону из росы на один вдох, и фейский двор признаёт его временным хранителем. За исполнение обряда отряд получает золото и припасы.","f":"Прозрачные капли обжигают голову Короля ледяным жаром, оставляя тяжёлое ранение.","v":{"nf":"Роса вспыхивает холодом, но Король не получает тяжёлого ранения. Церемония прерывается."}},"E280.2":{"s":"Вы отдаёте фейскому двору золото вместо согласия на корону. Придворные принимают подарок и отступают."},"E280.3":{"s":"Вы отказываете феям, не отводя взгляда от пустующего трона в каплях. Двор принимает решение и пропускает отряд.","f":"Фейская стража считает отказ нарушением древнего обычая и закрывает дорогу. Начинается стычка."},"E280.4":{"s":"Вы уходите до полного рассвета, не дав короне коснуться Короля. Первые солнечные лучи превращают её капли в обычную воду."},"E281.1":{"s":"Вы платите Пиксу восемь золотых, и он торжественно переставляет ваш табурет ближе к двери лекаря. Старушка с палкой грозит ему судом."},"E281.2":{"s":"Вы убираете шесть пустых табуретов Пикса, возвращая старушке её место. Она благодарит припасами, пока гоблин считает упущенную прибыль.","f":"Пикс предъявляет бумагу о «праве аренды ожидания», и очередь начинает спорить снова. Старушка остаётся позади табуретов."},"E281.3":{"s":"{{heroName}} доказывает, что табуреты не могут занимать очередь вместо больных. Пикс возвращает незаконно взятое золото.","f":"{{heroName}} не находит городского запрета на платные табуреты, и Пикс взыскивает золото за время проверки."},"E281.4":{"s":"Вы проходите мимо очереди к лекарю. Пикс уже предлагает старушке скидку на её собственное первое место."},"E282.1":{"s":"Вы покупаете у Кика страховой лист и получаете обещание вернуть деньги после смерти. Гоблин улыбается так, будто уже получил второй взнос."},"E282.2":{"s":"Вы вынуждаете Кика вернуть часть взносов клиентам и забираете законно присуждённое отряду золото.","f":"Гоблин вызывает охрану, обвиняя вас в попытке досрочно объявить страховой случай. Начинается стычка."},"E282.3":{"s":"{{heroName}} зачитывает договор вслух, и покупатели узнают, что выплаты юридически получить некому. Кик возвращает золото, чтобы избежать суда.","f":"{{heroName}} находит такую запутанную оговорку о получателях, что спор приходится отложить. Гоблин продолжает продавать полисы."},"E282.4":{"s":"Вы отказываетесь страховаться от собственной смерти у человека, который рассчитывает никогда не встретить получателя выплат. Кик уже ищет нового клиента."},"E283.1":{"s":"Суп оказывается вполне съедобным, а караван находит короткую дорогу по последнему видимому повороту. Оставшуюся провизию делят с отрядом.","f":"Половина слова «ОПАСНО» оказывается важнее рецепта, и за изгибом дороги вас поджидают вооружённые налётчики. Начинается стычка."},"E283.2":{"s":"Вы платите Реку за новый маршрут, и разведчик уводит караван подальше от котла Глюма. Повар клянётся больше не добавлять карты в суп."},"E283.3":{"s":"{{heroName}} восстанавливает дорогу по размокшему клочку и следам на земле. На правильном пути отряд находит золото и припасы.","f":"Догадка о повороте оказывается неверной, и {{affectedHeroName}} получает тяжёлое ранение в опасной местности.","v":{"nf":"Маршрут приводит к опасному спуску, но никто из допустимых бойцов не получает тяжёлого ранения. Дальше приходится искать обход."}},"E283.4":{"s":"Вы расходуете припасы на безопасный обход и оставляете Глюма с картографическим супом. Рек бережно прячет оставшийся уголок карты."},"E284.1":{"s":"Вы делаете ставку, а затем перепродаёте самую обычную медную монету следующему охотнику за редкостями. Выигрыш приносит золото.","f":"Аукционист бьёт молотком раньше вашей следующей ставки, и внесённое золото остаётся у торговцев."},"E284.2":{"s":"Вы показываете покупателям, что монета обычная, и Брык платит золотом за прекращение опасного для него торга.","f":"Покупатели считают разоблачение попыткой сорвать аукцион и окружают отряд с охраной. Начинается стычка."},"E284.3":{"s":"{{heroName}} выясняет, что первые ставки делали помощники Брыка, создавая видимость ажиотажа. Отряд получает золото за разоблачение.","f":"{{heroName}} не находит прямой связи между ставками и аукционистом. Монета продолжает дорожать."},"E284.4":{"s":"Вы наблюдаете, как потёртая монета достигает цены небольшого дома. Брык выглядит так, будто сам начинает верить в её ценность."},"E285.1":{"s":"Вы оплачиваете обратный путь, Зик ставит лестницу, и человек наконец спускается с крыши. Благодарный спасённый оставляет припасы."},"E285.2":{"s":"Вы требуете от Зика бесплатного спуска для застрявшего клиента. Гоблин уступает и возвращает часть золота.","f":"Зик заявляет, что вы посягаете на его бизнес, и вызывает охрану лестницы. Начинается стычка."},"E285.3":{"s":"{{heroName}} находит безопасное место для верёвочного спуска без лестницы Зика. Спасённый платит золотом за помощь.","f":"При спуске ломается опора, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Опора срывается, но никто из допустимых бойцов не получает тяжёлого ранения. Человек остаётся на крыше."}},"E285.4":{"s":"Вы уходите, пока Зик объявляет новую почасовую ставку за ожидание лестницы. С крыши раздаётся возмущённый крик."},"E286.1":{"s":"Вы ломаете внешний замок и вытаскиваете из сундука золотой кошель. Покупатель первым делом проверяет, что ещё было внутри.","f":"Защитный механизм ударяет по вскрывающим, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Сундук отвечает ударом защиты, но никто из допустимых бойцов не получает тяжёлого ранения. Содержимое остаётся запертым."}},"E286.2":{"s":"Вы платите Тику за «аварийный ключ», и гоблин торжественно вручает ещё один металлический предмет. Покупатель требует немедленно проверить, открывает ли он хоть что-нибудь."},"E286.3":{"s":"{{heroName}} находит у сундука скрытый нижний засов и открывает его, не повреждая содержимое. Покупатель благодарит золотом и припасами.","f":"Защитные петли резко сжимаются, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Петли срываются с направляющих, но никто из допустимых бойцов не получает тяжёлого ранения. Сундук остаётся закрытым."}},"E286.4":{"s":"Вы оставляете покупателя с самым безопасным сундуком в мире. Изнутри снова слышится слабый стук, а Тик повторяет условия гарантии."},"E287.1":{"s":"Вы заставляете Крака признать подделку, и гоблин возвращает золото Фаэлю и отряду. Искрящий нимб наконец снимают.","f":"Крак заявляет, что товар куплен без права возврата, и зовёт охрану. Начинается стычка."},"E287.2":{"s":"Вы отдаёте Краку золото и покупаете припасы вместо новой небесной принадлежности. Фаэль просит не брать ничего светящегося."},"E287.3":{"s":"{{heroName}} находит в торговых правилах пункт о ложном происхождении товара. Крак вынужден вернуть золото за ненастоящий нимб.","f":"{{heroName}} обнаруживает, что в квитанции написано лишь «сияющее кольцо». Возврат не удаётся оформить."},"E287.4":{"s":"Вы проходите мимо рынка, где Фаэль борется с перегретым нимбом. Крак уже предлагает охлаждающую подставку за отдельную плату."},"E288.1":{"s":"Вы помогаете Одо установить скобу, и недостающая половина радуги выравнивается. Дварф благодарит золотом за техническое содействие.","f":"Металл снова меняет порядок цветов, и Одо признаёт, что проблема оказалась сложнее обычной фермы. Исправить радугу не удаётся."},"E288.2":{"s":"Вы помогаете Мелли убрать железо, и цвета постепенно возвращаются на свои места. Фея делится припасами в благодарность.","f":"Одо отказывается снять опору с недостроенной радуги. Спор двух мастеров продолжается."},"E288.3":{"s":"{{heroName}} ставит временную опору так, чтобы ни свет, ни цвета не приходилось прибивать железом. Одо и Мелли благодарят золотом и припасами.","f":"При установке опоры {{affectedHeroName}} получает тяжёлое ранение от сорвавшейся скобы.","v":{"nf":"Временная скоба срывается, но никто из допустимых бойцов не получает тяжёлого ранения. Радуга остаётся надломленной."}},"E288.4":{"s":"Вы оставляете дварфа прикручивать радугу, а фею — возмущаться железом на цветах. Порядок оттенков меняется ещё раз."},"E289.1":{"s":"Вы поддерживаете Брука и помогаете устроить для призрачного ребёнка безопасное место у очага. Орк благодарит припасами за понимание.","f":"Шаманка настаивает, что призрачному ребёнку нужна память о доме, а не новая постель. Брук остаётся без поддержки старейшин."},"E289.2":{"s":"Вы помогаете шаманке завершить обряд, и ребёнок видит дорогу за пределы руин. Брук прощается с ним, а шаманка передаёт золото.","f":"Призрак не хочет покидать Брука и прячется за его спиной. Обряд приходится прекратить."},"E289.3":{"s":"{{heroName}} находит в памяти ребёнка имя и дорогу к его прежнему дому. Брук благодарит золотом и припасами за возвращённое воспоминание.","f":"Обряд памяти отвечает тяжёлым ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Память ребёнка сопротивляется вмешательству, но никто из допустимых бойцов не получает тяжёлого ранения. Его имя остаётся забытым."}},"E289.4":{"s":"Вы оставляете Брука с ребёнком, которого видно насквозь. Орк осторожно объясняет ему, где в доме будут стоять башмаки."},"E290.1":{"s":"Вы разрезаете паутину и опускаете Ториэля на землю. Ангел благодарит золотом за спасённые крылья и достоинство.","f":"Паук принимает разрезание сети за нападение и бросается на отряд. Начинается стычка."},"E290.2":{"s":"Вы оставляете пауку припасы, и тот нехотя отводит лапу от Вeсы. Ториэля наконец можно снять с ловушки."},"E290.3":{"s":"{{heroName}} отвлекает паука движением седла, пока Веса освобождает ангельские крылья. Ториэль платит золотом и выдаёт припасы.","f":"Паук срывает попытку освобождения, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Паук закрывает доступ к сети, но никто из допустимых бойцов не получает тяжёлого ранения. Ангел остаётся висеть над дорогой."}},"E290.4":{"s":"Вы оставляете Весу и Ториэля разбираться с правом на паутину. Ангел просит хотя бы повернуть его лицом к дороге."}});
export { OUTCOMES_E221_E290 };
